{
  "name": "inject-user-id",
  "version": "0.3.0",
  "description": "OpenCode plugin that injects metadata.user_id into configured model request URLs for prompt-cache stickiness",
  "license": "MIT",
  "author": "heiyan-2020",
  "type": "module",
  "exports": "./index.ts",
  "main": "./index.ts",
  "scripts": {
    "test": "INJECT_HOST=api.claudecode.net.cn,relay.example.com,https://prefix.example.com/api/v1 INJECT_ID=acct-42 node --experimental-strip-types test.ts"
  },
  "files": [
    "index.ts",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "llm",
    "metadata",
    "cache"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/heiyan-2020/inject-user-id.git"
  },
  "homepage": "https://github.com/heiyan-2020/inject-user-id#readme",
  "bugs": {
    "url": "https://github.com/heiyan-2020/inject-user-id/issues"
  },
  "publishConfig": {
    "access": "public"
  }
}

/**
 * OpenCode plugin: inject `metadata.user_id` into selected model request
 * bodies. Everything else passes through untouched.
 *
 * Why: a relay that routes by `metadata.user_id` can pin a session's requests
 * to one upstream account, keeping prompt-cache hit rate high — without a
 * separate request-rewriting proxy. The provider `baseURL` can then point
 * straight at the remote relay (no local loopback proxy).
 *
 * Gating:
 *   - INJECT_HOST selects target hosts/URLs. It is comma-separated and accepts
 *     bare hosts (matching that host and subdomains) or full URL prefixes.
 *   - only POSTs to /messages or /chat/completions with a JSON body are touched.
 *
 * Mirrors @lucentia/opencode-trace's fetch-wrap pattern (v1.3 function +
 * v1.4 `.server`); composes with other plugins.
 */

const USER_ID = process.env.INJECT_ID || "stable-user-or-session-id-xxxxxxx123"

const TARGETS = (process.env.INJECT_HOST || "")
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean)

// model POST endpoints with a JSON body
const MODEL_PATH = /\/(?:v1\/)?(?:messages|chat\/completions)\b/

let orig: typeof globalThis.fetch | undefined

function matchesTarget(url: URL): boolean {
  return TARGETS.some((target) => {
    if (/^https?:\/\//i.test(target)) {
      return url.href.startsWith(target)
    }
    return url.hostname === target || url.hostname.endsWith("." + target)
  })
}

async function injectingFetch(
  input: Parameters<typeof globalThis.fetch>[0],
  init?: Parameters<typeof globalThis.fetch>[1],
): Promise<Response> {
  const req = new Request(input, init)

  // gate 1 — only configured target hosts/URLs
  let url: URL
  try {
    url = new URL(req.url)
  } catch {
    return orig!(req)
  }
  if (!matchesTarget(url)) return orig!(req)

  // gate 2 — only POSTs to a model endpoint with a JSON body
  if (req.method !== "POST" || !MODEL_PATH.test(req.url)) return orig!(req)
  let body: any
  try {
    body = JSON.parse(await req.clone().text())
  } catch {
    return orig!(req)
  }
  if (!body || typeof body !== "object" || Array.isArray(body)) return orig!(req)

  body.metadata = { ...(body.metadata ?? {}), user_id: USER_ID }
  const headers = new Headers(req.headers)
  headers.delete("content-length") // let fetch recompute for the new body
  return orig!(new Request(req.url, {
    method: req.method,
    headers,
    body: JSON.stringify(body),
  }))
}

const main: (() => Promise<object>) & { id?: unknown; server?: unknown } =
  async () => {
    if (!orig) {
      orig = globalThis.fetch.bind(globalThis)
      globalThis.fetch = injectingFetch
    }
    return {}
  }

main.id = "heiyan-2020.inject-user-id"
main.server = main // opencode v1.4 calls default.server()
export default main
